 resourcefalsestream_socket_server
 stringaddress
 interror_code&null;
 stringerror_message&null;
 intflagsSTREAM_SERVER_BIND | STREAM_SERVER_LISTEN
 resourcenullcontext&null;



 Creates a stream or datagram socket on the specified
 address.    


 This function only creates a socket, to begin accepting connections
 use stream_socket_accept, which does not work with a
 udp:// server: use stream_socket_recvfrom
 instead.

  &reftitle.examples;



    Using TCP server sockets


<?php
$socket = stream_socket_server("tcp://0.0.0.0:8000", $errno, $errstr);
if (!$socket) {
  echo "$errstr ($errno)\n";
} else {
  while ($conn = stream_socket_accept($socket)) {
    fwrite($conn, 'The local time is ' . date('n/j/Y g:i a') . "\n");
    fclose($conn);
  }
  fclose($socket);
}






   The example below shows how to act as a time server which responds to
   UDP queries sent to port 1113, such as the one of the example on
   stream_socket_client once its port is changed to
   1113.


     Most systems require root access to create a server socket on a port
     below 1024.



    Using UDP server sockets


<?php
$socket = stream_socket_server("udp://127.0.0.1:1113", $errno, $errstr, STREAM_SERVER_BIND);
if (!$socket) {
    die("$errstr ($errno)");
}

do {
    $pkt = stream_socket_recvfrom($socket, 1, 0, $peer);
    echo "$peer\n";
    stream_socket_sendto($socket, date("D M j H:i:s Y\r\n"), 0, $peer);
} while ($pkt !== false);
